 for item in select value from jsonb_array_elements(p_value->'offers') loop
  if exists(select 1 from jsonb_array_elements_text(item->'areaIds') a where not(a.value=any(area_ids))) then return false; end if;
  if item->'validFrom'<>'null'::jsonb and item->'validUntil'<>'null'::jsonb and (item->>'validFrom')::date>(item->>'validUntil')::date then return false;end if;
  if item->'validFrom'<>'null'::jsonb then perform (item->>'validFrom')::date;end if;
  if item->'validUntil'<>'null'::jsonb then perform (item->>'validUntil')::date;end if;
  if exists(select 1 from jsonb_array_elements(item->'schedule') s where s->>'start'=s->>'end') then return false;end if;
  for price in select value from jsonb_array_elements(item->'prices') loop
   if price->'max'<>'null'::jsonb and (price->>'min')::numeric>(price->>'max')::numeric or price->'minimumAge'<>'null'::jsonb and price->'maximumAge'<>'null'::jsonb and (price->>'minimumAge')::integer>(price->>'maximumAge')::integer then return false;end if;
  end loop;
 end loop;
 -- Check conditions on every property and price; no prose-based eligibility.
 rows:=p_value->'properties';
 for item in select value from jsonb_array_elements(p_value->'areas') loop rows:=rows||(item->'properties');end loop;
 for item in select value from jsonb_array_elements(p_value->'offers') loop rows:=rows||(item->'properties')||(item->'prices');end loop;
 for property in select value from jsonb_array_elements(rows) loop
  item:=property->'conditions';
  if item->'validFrom'<>'null'::jsonb then perform (item->>'validFrom')::date;end if;
  if item->'validUntil'<>'null'::jsonb then perform (item->>'validUntil')::date;end if;
  if item->'validFrom'<>'null'::jsonb and item->'validUntil'<>'null'::jsonb and (item->>'validFrom')::date>(item->>'validUntil')::date then return false;end if;
 end loop;
